logger.message:
#[%dw 2.0
output application/json skipNullOn="everywhere"
---
{
    "log-message":{
        "message":"prc api request flow started",
        "log-tracepoint": "BEFORE_REQUEST",
        "Log-Level":"INFO",
        "Environment": p('mule.env'),
        "correlationId": correlationId,
        "Payload": null
    }
}]

#[%dw 2.0
output application/json skipNullOn="everywhere"
---
{
    "log-message":{
        "message":"prc api request flow started",
        "log-tracepoint": "BEFORE_REQUEST",
        "Log-Level":"DEBUG",
        "Environment": p('mule.env'),
        "correlationId": correlationId,
        "Payload": write(payload,"application/json")        
    }
}]

set-variable.value:
#[output application/json
---
{
	"errorDescription": if(typeOf(error.errorMessage.payload) ~= "Binary") error.description else (error.errorMessage.payload.errorMessage default error.description),
	"errorType": (error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")
}]

logger.message:
#[%dw 2.0
output application/json skipNullOn="everywhere"
---
{
    "log-message":{
        "message":"prc api request flow ended",
        "log-tracepoint": "AFTER_REQUEST",
        "Log-Level":"DEBUG",
        "Environment": p('mule.env'),
        "correlationId": correlationId,
        "Payload": write(payload,"application/json")        
    }
}]

